private void releaseQueue(ChannelHandlerContext ctx, boolean active) {
    // Handle all the queued packets
    Object msg;
    while ((msg = this.queue.poll()) != null) {
      if (active) {
        ctx.fireChannelRead(msg);
      } else {
        ReferenceCountUtil.release(msg);
      }
    }
    this.queueSize = 0;
  }

