void handleClientAck(Acknowledge msg, CustomPayloadEvent.Context ctx) {
        ctx.setPacketHandled(true);
        var consumer = this.pendingAcknowledgments.remove(msg.token());
        if (consumer != null) {
            LOGGER.debug(MARKER, "Received acknowledgement {} from client", msg.token());
            consumer.accept(msg, ctx);
        } else {
            LOGGER.error(MARKER, "Received unknown acknowledgement {} from client", msg.token());
            ctx.getConnection().disconnect(Component.literal("Illegal Acknowledge packet received, unknown token: " + Integer.toHexString(msg.token())));
        }
    }

private <T> CompletableFuture<T> asyncFailableFuture(Callable<T> call, Executor exec) {
        final CompletableFuture<T> ret = new CompletableFuture<>();
        exec.execute(() -> {
            try {
                ret.complete(call.call());
            } catch (Throwable e) {
                ret.completeExceptionally(e);
            }
        });
        return ret;
    }

@Inject(method = "handleDisconnection", at = @At("RETURN"))
    private void impl$onDisconnected(final CallbackInfo ci) {
        if (!this.disconnectionHandled) {
            //Vanilla has race condition here where this might be called
            //while the channel is still open
            return;
        }
        this.impl$disconnected = true;
        this.impl$engineConnection.disconnected();
        this.impl$closePendingActions();
    }

@Inject(method = "wrapRunnable(Ljava/lang/Runnable;)Lnet/minecraft/server/TickTask;", at = @At("RETURN"))
    private void tracker$associatePhaseContextWithWrappedTask(final Runnable runnable, final CallbackInfoReturnable<TickTask> cir) {
        final TickTask returnValue = cir.getReturnValue();
        if (!PhaseTracker.SERVER.onSidedThread()) {
            final PhaseContext<@NonNull ?> phaseContext = PhaseTracker.getInstance().getPhaseContext();
            if (phaseContext.isEmpty()) {
                return;
            }
            phaseContext.foldContextForThread(((TickTaskBridge) returnValue));
        }
    }

@SubscribeEvent
        public static void initRegistries(FMLConstructModEvent event)
        {
            event.enqueueWork(() ->
            {
                if (REGISTRIES_INITIALIZED) return;

                ColdSweat.LOGGER.info("Gathering Cold Sweat registries");
                // Gather modded registries
                AddRegistriesEvent addRegistriesEvent = new AddRegistriesEvent();

                // Check if the event bus is closed
                boolean busWasClosed = !MinecraftForge.EVENT_BUS.post(new ProbeEventBusEvent());
                // Start the event bus temporarily
                MinecraftForge.EVENT_BUS.start();
                // Post AddRegistriesEvent to the event bus
                MinecraftForge.EVENT_BUS.post(addRegistriesEvent);
                // Re-close the event bus if it was closed before
                if (busWasClosed)
                {
                    ColdSweat.LOGGER.info("The event bus was started early to gather Cold Sweat registries; it will now be stopped again until the correct loading phase.");
                    try
                    {   Field shutdown = EventBus.class.getDeclaredField("shutdown");
                        shutdown.setAccessible(true);
                        shutdown.set(MinecraftForge.EVENT_BUS, true);
                    }
                    catch (Exception e)
                    {   ColdSweat.LOGGER.error("Failed to re-shutdown the event bus after gathering Cold Sweat registries", e);
                    }
                }

                // Add registries via dummy NewRegistry event
                DataPackRegistryEvent.NewRegistry dummyEvent = new DataPackRegistryEvent.NewRegistry();
                for (RegistryHolder holder : ModRegistries.getRegistries().values())
                {   dummyEvent.dataPackRegistry(holder.key(), holder.codec(), holder.codec());
                }
                try
                {   Method process = DataPackRegistryEvent.NewRegistry.class.getDeclaredMethod("process");
                    process.setAccessible(true);
                    process.invoke(dummyEvent);
                }
                catch (Exception ignored) {}

                REGISTRIES_INITIALIZED = true;
            });
        }

public void recheckOpeners(Entity entity) {
		Level level = entity.level();
		List<Player> playersWithStorageOpen = getPlayersWithContainerOpen(level, entity.blockPosition());
		maxInteractionRange = 0.0;

		for (Player player : playersWithStorageOpen) {
			maxInteractionRange = Math.max(player.entityInteractionRange(), maxInteractionRange);
		}

		int numberOfPlayers = playersWithStorageOpen.size();
		if (openCount != numberOfPlayers) {
			if (numberOfPlayers != 0 && openCount == 0) {
				onOpen();
				level.gameEvent(null, GameEvent.CONTAINER_OPEN, entity.blockPosition());
			} else if (numberOfPlayers == 0) {
				onClose();
				level.gameEvent(null, GameEvent.CONTAINER_CLOSE, entity.blockPosition());
			}

			openCount = numberOfPlayers;
		}

		if (numberOfPlayers > 0) {
			nextOpenRecheck = level.getGameTime() + CHECK_TICK_DELAY;
		}
	}

private void updateQueue(Map<@Nullable IRenderSetup, Queue<GTParticle>> renderQueue) {
        Iterator<Queue<GTParticle>> it = renderQueue.values().iterator();
        while (it.hasNext()) {
            Queue<GTParticle> particlesForSetup = it.next();

            Iterator<GTParticle> particles = particlesForSetup.iterator();
            while (particles.hasNext()) {
                GTParticle particle = particles.next();

                if (particle.isAlive()) {
                    try {
                        particle.onUpdate();
                    } catch (RuntimeException exception) {
                        GTCEu.LOGGER.error("Particle update error: {}", particle, exception);
                        particle.setExpired();
                    }
                    if (particle.isAlive()) continue;
                }

                particles.remove();
            }

            if (particlesForSetup.isEmpty()) {
                it.remove();
            }
        }
    }

