@Override
    public void tick() {
        super.tick();
        move(MoverType.SELF, getDeltaMovement());

        if (tickCount == 1) {
            if (level().isClientSide) {
                MMCommon.PROXY.playIceBreathSound(this);
            }
        }

        List<Entity> entitiesHit = getEntitiesNearby(2);
        if (!entitiesHit.isEmpty()) {
            for (Entity entity : entitiesHit) {
                if (entity instanceof ItemEntity) continue;
                if (entity == getCaster()) continue;
                if (entity instanceof ItemEntity) continue;
                if (entity.getType().is(EntityTypeTags.FREEZE_IMMUNE_ENTITY_TYPES) || entity instanceof EnderDragon) continue;
                if (entity.hurt(damageSources().freeze(), 3f * ConfigHandler.COMMON.MOBS.FROSTMAW.combatConfig.attackMultiplier.get().floatValue())) {
                    if (entity instanceof LivingEntity) DataHandler.getData(entity, DataHandler.FROZEN_DATA).addFreezeProgress((LivingEntity) entity, 1);
                }
            }
        }

        if (!level().noCollision(this, getBoundingBox().inflate(0.15))) {
            explode();
        }

        if (level().isClientSide) {
            float scale = 2f;
            double x = getX();
            double y = getY() + getBbHeight() / 2;
            double z = getZ();
            double motionX = getDeltaMovement().x;
            double motionY = getDeltaMovement().y;
            double motionZ = getDeltaMovement().z;
            for (int i = 0; i < 4; i++) {
                double xSpeed = scale * 0.01 * (random.nextFloat() * 2 - 1);
                double ySpeed = scale * 0.01 * (random.nextFloat() * 2 - 1);
                double zSpeed = scale * 0.01 * (random.nextFloat() * 2 - 1);
                float value = random.nextFloat() * 0.15f;
                level().addParticle(new ParticleCloud.Data(0.75f + value, 0.75f + value,1f, scale * (10f + random.nextFloat() * 20f), 20, ParticleCloud.EnumCloudBehavior.SHRINK, 1f), x + xSpeed, y + ySpeed, z + zSpeed, xSpeed, ySpeed, zSpeed);
            }
            for (int i = 0; i < 1; i++) {
                double xSpeed = scale * 0.01 * (random.nextFloat() * 2 - 1);
                double ySpeed = scale * 0.01 * (random.nextFloat() * 2 - 1);
                double zSpeed = scale * 0.01 * (random.nextFloat() * 2 - 1);
                level().addParticle(new ParticleCloud.Data(1f, 1f, 1f, scale * (5f + random.nextFloat() * 10f), 40, ParticleCloud.EnumCloudBehavior.SHRINK, 1f), x, y, z, xSpeed, ySpeed, zSpeed);
            }

            for (int i = 0; i < 5; i++) {
                double xSpeed = scale * 0.05 * (random.nextFloat() * 2 - 1);
                double ySpeed = scale * 0.05 * (random.nextFloat() * 2 - 1);
                double zSpeed = scale * 0.05 * (random.nextFloat() * 2 - 1);
                level().addParticle(new ParticleSnowFlake.Data(40, false), x - 20 * (xSpeed) + motionX, y - 20 * ySpeed + motionY, z - 20 * zSpeed + motionZ, xSpeed, ySpeed, zSpeed);
            }

            float yaw = (float) Math.atan2(motionX, motionZ);
            float pitch = (float) (Math.acos(motionY / Math.sqrt(motionX * motionX + motionY * motionY + motionZ * motionZ)) + Math.PI / 2);
            if (tickCount % 3 == 0) {
                level().addParticle(new ParticleRing.Data(yaw, pitch, 40, 0.9f, 0.9f, 1f, 0.4f, (int) (scale * 16), false, ParticleRing.EnumRingBehavior.GROW_THEN_SHRINK), x + 1.5f * motionX, y + 1.5f *motionY, z + 1.5f * motionZ, 0, 0, 0);
            }

            if (tickCount == 1) {
                level().addParticle(new ParticleRing.Data(yaw, pitch, 20, 0.9f, 0.9f, 1f, 0.4f, (int) (scale * 16), false, ParticleRing.EnumRingBehavior.GROW), x, y, z, 0, 0, 0);
            }
        }
        if (tickCount > 50) discard() ;
    }

public static Pair<Boolean, Boolean> dealMixedDamage(LivingEntity target, DamageSource source1, float amount1, DamageSource source2, float amount2) {
        if (target.level().isClientSide()) return Pair.of(false, false);
        boolean flag1 = source1.getEntity() != null && target.isAlliedTo(source1.getEntity());
        boolean flag2 = source2.getEntity() != null && target.isAlliedTo(source2.getEntity());
        if(flag1 || flag2) return Pair.of(false, false);
        LivingData data = DataHandler.getData(target, DataHandler.LIVING_DATA);
        data.setLastDamage(-1);
        float damageSoFar = 0;
        float origLastDamage = target.lastHurt;
        boolean hit1 = target.hurt(source1, amount1);
        boolean hit1Registered = hit1;
        if (data.getLastDamage() != -1) {
            hit1Registered = true;
        }
        if (data.getLastDamage() != 0) {
            damageSoFar += amount1;
        }
        target.lastHurt = Math.max(target.lastHurt - amount1, 0);
        data.setLastDamage(-1);
        boolean hit2 = target.hurt(source2, amount2);
        if (data.getLastDamage() != 0) {
            damageSoFar += amount2;
        }
        target.lastHurt = origLastDamage;
        if (damageSoFar > target.lastHurt) target.lastHurt = damageSoFar;

        if (hit2 && hit1Registered) {
            onHit2(target, source2);
            if (target instanceof Player) {
                SoundEvent sound = SoundEvents.PLAYER_HURT;
                if (source2.is(DamageTypeTags.IS_FIRE)) sound = SoundEvents.PLAYER_HURT_ON_FIRE;
                else if (source2.is(DamageTypeTags.IS_DROWNING)) sound = SoundEvents.PLAYER_HURT_DROWN;
                target.playSound(sound, 1F, getSoundPitch(target));
            }
        }
        return Pair.of(hit1, hit2);
    }

@Override
    public Set<ScheduledTask> tasks(final PluginContainer plugin) {
        final String testOwnerId = Objects.requireNonNull(plugin, "plugin").metadata().id();

        final Set<ScheduledTask> allTasks = this.tasks();
        final Iterator<ScheduledTask> it = allTasks.iterator();

        while (it.hasNext()) {
            final String taskOwnerId = it.next().task().plugin().metadata().id();
            if (!testOwnerId.equals(taskOwnerId)) {
                it.remove();
            }
        }

        return allTasks;
    }

void popFrameMutator(final PhaseContext<?> context) {
        final @Nullable PhaseContext<?> peek = this.phaseContextProviders.peek();
        if (peek == null) {
            return;
        }
        if (peek != context) {
            // there's an exception to be thrown or printed out at least, basically a copy of popFrame.
            System.err.println("oops. corrupted phase context providers!");
        }
        this.phaseContextProviders.pop();
        if (this.phaseContextProviders.isEmpty()) {
            // if we're empty, we don't need to bother with the context providers
            // because there's nothing to push.
            this.pendingProviders.compareAndSet(true, false);
        }

    }

@Redirect(method = "execute",
            at = @At(
                    value = "INVOKE",
                    target = "Ljava/lang/Runnable;run()V",
                    remap = false))
    private void tracker$callOnMainThreadWithPhaseState(final Runnable runnable) {
        // The server thread has been killed, we are unable to process requests any further.
        if (this.tracker$isServerAndIsServerStopped()) {
            this.dropAllTasks();
            return;
        }

        try (final BasicPluginContext context = PluginPhase.State.SCHEDULED_TASK.createPhaseContext(PhaseTracker.getInstance())
                .source(runnable)) {
            context.buildAndSwitch();
            runnable.run();
        }
    }

private void sendRegistries(Acknowledge msg, CustomPayloadEvent.Context ctx) {
        if (msg.token() != expectedToken) {
            LOGGER.error(MARKER, "Received unknown acknowledgement received {} exptected {}", msg.token(), expectedToken);
            ctx.getConnection().disconnect(Component.literal("Illegal Acknowledge packet received, unknown token: " + msg.token()));
            return;
        }

        // We've got no more to send, so finish this task!
        if (this.snapshot == null || this.snapshot.isEmpty()) {
            taskCtx.finish(type());
            return;
        }

        // Send the next registry!
        var name = this.snapshot.keySet().iterator().next();
        var data = this.snapshot.remove(name);
        expectedToken = this.handler.expectAck(this::sendRegistries);
        NetworkInitialization.CONFIG.reply(new RegistryData(expectedToken, name, data), ctx);
    }

public void runTasks() {
        if (tasks.isEmpty()) return;
        LOGGER.debug(LOADING, "Dispatching synchronous work for work queue {}: {} jobs", modLoadingStage, tasks.size());
        RuntimeException aggregate = new RuntimeException();
        Stopwatch timer = Stopwatch.createStarted();
        for (TaskInfo t : tasks) {
            makeRunnable(t, Runnable::run, aggregate);
        }
        timer.stop();
        if (aggregate.getSuppressed().length > 0) {
            LOGGER.fatal(
                    LOADING,
                    "Synchronous work queue completed exceptionally in {}, see suppressed exceptions for details:",
                    timer,
                    aggregate
            );
            throw aggregate;
        } else {
            LOGGER.debug(LOADING, "Synchronous work queue completed in {}", timer);
        }
    }

@SuppressWarnings("rawtypes")
    private void checkProviders() {
        // Seriously, ok so, uh...
        if (!this.pendingProviders.compareAndSet(true, false)) {
            return; // we've done our work already
        }
        // Then, we want to inversely iterate the stack (from bottom to top)
        // to properly mimic as though the frames were created at the time of the
        // phase switches. It does not help the debugging of cause frames
        // except for this method call-point.
        for (final Iterator<PhaseContext<@NonNull ?>> iterator = this.phaseContextProviders.descendingIterator(); iterator.hasNext(); ) {
            final PhaseContext<@NonNull ?> context = iterator.next();
            final StackFrame frame = this.pushCauseFrame(); // these should auto close
            context.getFrameModifier().accept(frame); // The frame will be auto closed by the phase context
        }
        // Clear the list since everything is now loaded.
        // PhaseStates will handle automatically closing their frames
        // and then any new phase states that get entered can still be lazily loaded afterwards, while
        // we take advantage of the already made modifications are being tracked by the stack manager
        this.phaseContextProviders.clear();
    }

@SuppressWarnings({"unchecked"})
	@WrapOperation(method = "lambda$load$2", at = @At(value = "NEW", target = "net/minecraft/resources/RegistryLoadTask$PendingRegistration"))
	private <T> RegistryLoadTask.PendingRegistration<?> modify(ResourceKey<T> key, Either<T, Exception> value, RegistrationInfo registrationInfo, Operation<RegistryLoadTask.PendingRegistration<T>> original, @Local(argsOnly = true) Resource resource) {
		if (value.left().isPresent()) {
			T leftValue = value.left().get();
			T modified = null;

			if (leftValue instanceof Enchantment enchantment) {
				modified = (T) EnchantmentUtil.modify((ResourceKey<Enchantment>) key, enchantment, ResourceUtil.determineSource(resource), registryInfoLookup);
			} else if (leftValue instanceof BlockTransformer blockTransformer) {
				modified = (T) BlockTransformerHelperImpl.modify((ResourceKey<BlockTransformer>) key, blockTransformer, ResourceUtil.determineSource(resource), registryInfoLookup);
			}

			if (modified != null) {
				// Clear the knownPackInfo to force the server to sync the data pack to the client
				registrationInfo = new RegistrationInfo(Optional.empty(), registrationInfo.lifecycle());
				value = Either.left(modified);
			}
		}

		return original.call(key, value, registrationInfo);
	}

