public void close() {
        this.running = false;
        // Cancel all tasks
        final Set<ScheduledTask> tasks = this.tasks();
        tasks.forEach(ScheduledTask::cancel);

        // Shut down the executor
        this.executor.shutdown();

        try {
            if (!this.executor.awaitTermination(5, TimeUnit.SECONDS)) {
                new PrettyPrinter()
                        .add("Sponge async scheduler failed to shut down in 5 seconds! Tasks that may have been active:")
                        .addWithIndices(tasks)
                        .add()
                        .add("We will now attempt immediate shutdown.")
                        .log(SpongeCommon.logger(), Level.WARN);

                this.executor.shutdownNow();
            }
        } catch (final InterruptedException e) {
            SpongeCommon.logger().error("The async scheduler was interrupted while awaiting shutdown!");
        }
    }

@SuppressWarnings("unchecked")
	@WrapOperation(method = "lambda$load$2", at = @At(value = "INVOKE", target = "Lnet/minecraft/resources/RegistryLoadTask$PendingRegistration;loadFromResource(Lcom/mojang/serialization/Decoder;Lnet/minecraft/resources/RegistryOps;Lnet/minecraft/resources/ResourceKey;Lnet/minecraft/server/packs/resources/Resource;)Lcom/mojang/datafixers/util/Either;"))
	private <T> Either<T, Exception> modifyAdvancement(Decoder<T> decoder, RegistryOps<JsonElement> ops, ResourceKey<T> key, Resource resource, Operation<Either<T, Exception>> original) {
		Either<T, Exception> result = original.call(decoder, ops, key, resource);

		if (!key.isFor(Registries.ADVANCEMENT)) {
			return result;
		}

		HolderLookup.Provider provider = AdvancementUtil.getActiveReloadProvider(this.resourceManager);

		RegistryOps.RegistryInfoLookup registryInfoLookup = ops::getter;

		if (provider == null) {
			return result;
		}

		// Merge the HolderLookup.Provider and RegistryOps.RegistryInfoLookup into a HolderLookup.Provider with access to reloadable registries.
		var fullProvider = new AdvancementHolderProvider(registryInfoLookup, provider);

		return result.mapLeft(value -> (T) AdvancementUtil.modifyAdvancement(
				key.identifier(),
				(Advancement) value,
				AdvancementUtil.determineSource(resource),
				fullProvider
		));
	}

@SuppressWarnings("unchecked")
	@WrapOperation(method = "lambda$load$2", at = @At(value = "INVOKE", target = "Lnet/minecraft/resources/RegistryLoadTask$PendingRegistration;loadFromResource(Lcom/mojang/serialization/Decoder;Lnet/minecraft/resources/RegistryOps;Lnet/minecraft/resources/ResourceKey;Lnet/minecraft/server/packs/resources/Resource;)Lcom/mojang/datafixers/util/Either;"))
	private <T> Either<T, Exception> modifyLootTable(Decoder<T> decoder, RegistryOps<JsonElement> ops, ResourceKey<T> key, Resource resource, Operation<Either<T, Exception>> original) {
		Either<T, Exception> result = original.call(decoder, ops, key, resource);

		if (!key.isFor(Registries.LOOT_TABLE)) {
			return result;
		}

		HolderLookup.Provider provider = LootUtil.getActiveReloadProvider(this.resourceManager);

		RegistryOps.RegistryInfoLookup registryInfoLookup = ops::getter;

		if (provider == null) {
			return result;
		}

		// Merge the HolderLookup.Provider and RegistryOps.RegistryInfoLookup into a HolderLookup.Provider with access to reloadable registries.
		var fullProvider = new LootTableHolderProvider(registryInfoLookup, provider);

		return result.mapLeft(value -> (T) LootUtil.modifyLootTable(
				(ResourceKey<LootTable>) key,
				(LootTable) value,
				LootUtil.determineSource(resource),
				fullProvider
		));
	}

public static void syncPendingConfigs(MinecraftServer server) {
        synchronized (lock) {
            for (var player : server.getPlayerList().getPlayers()) {
                if (!player.connection.hasChannel(ConfigFilePayload.TYPE)) {
                    continue; // Only sync configs to NeoForge clients supporting config sync
                }

                if (player.connection.getConnection().isMemoryConnection()) {
                    continue; // Do not sync server configs with ourselves
                }

                var toSync = configsToSync.get(player.connection.getConnection());
                if (toSync == null) {
                    // null for GameTestPlayer. Should not happen for normal players though.
                    if (player.getClass() == ServerPlayer.class) {
                        throw new IllegalStateException("configsToSync should contain an entry for player " + player.getName());
                    } else {
                        continue;
                    }
                }
                toSync.forEach((fileName, data) -> {
                    PacketDistributor.sendToPlayer(player, new ConfigFilePayload(fileName, data));
                });
                toSync.clear();
            }
        }
    }

@Redirect(method = "lambda$prepareTickingChunk$27",
        at = @At(value = "INVOKE", target = "Lnet/minecraft/server/level/ServerLevel;startTickingChunk(Lnet/minecraft/world/level/chunk/LevelChunk;)V"))
    private void tracker$wrapUnpackTicks(final ServerLevel level, final LevelChunk chunk) {
        if (!PhaseTracker.SERVER.onSidedThread()) {
            new PrettyPrinter(60).add("Illegal Async Chunk Unpacking").centre().hr()
                .addWrapped("Someone is attempting to unpack chunk scheduled updates while off the main thread, this is" +
                    "generally unsupported and Sponge would appreciate a report about this. Please attach " +
                    "the generated classes output as a zip file after enabling -Dmixin.debug.export=true " +
                    "and request triage support on discord. Do NOT report as an issue on GitHub.")
                .add()
                .add(" %s : %s", "Chunk Pos", chunk.getPos().toString())
                .add()
                .add(new Exception("Async Chunk Scheduling Detected"))
                .log(SpongeCommon.logger(), Level.ERROR);
            return;
        }
        if (PhaseTracker.getInstance().getCurrentState() == GenerationPhase.State.CHUNK_LOADING) {
            return;
        }
        try (final PhaseContext<@NonNull ?> ctx = GenerationPhase.State.CHUNK_LOADING.createPhaseContext(PhaseTracker.getInstance())
            .source(chunk)
            .world(level)
            .chunk(chunk)) {
            ctx.buildAndSwitch();
            chunk.unpackTicks(level.getLevelData().getGameTime());
        }

    }

public static void registerEventListeners() {
        for (var modContainer : ModList.get().getSortedMods()) {
            var modBus = modContainer.getEventBus();
            if (modBus != null) {
                modBus.addListener(ModConfigEvent.Reloading.class, event -> {
                    var config = event.getConfig();
                    if (config.getType() != ModConfig.Type.SYNCED) {
                        return;
                    }
                    var loadedConfig = config.getLoadedConfig();
                    if (loadedConfig == null) {
                        return;
                    }

                    var configFormat = loadedConfig.config().configFormat();
                    if (configFormat.isInMemory()) {
                        return; // An in-memory format indicates that we received this config from a server and shouldn't try to sync it
                    }

                    // Write config bytes and queue for syncing to all connected players.
                    var bytes = configFormat.createWriter().writeToString(loadedConfig.config()).getBytes(StandardCharsets.UTF_8);
                    synchronized (lock) {
                        for (var toSync : configsToSync.values()) {
                            toSync.put(config.getFileName(), bytes);
                        }
                    }
                });
            }
        }
    }

public static void clientInit() {
		// Reference cleanup for the locally stored addon if we are disconnected
		ClientPlayConnectionEvents.DISCONNECT.register((listener, client) -> {
			currentPlayAddon = null;
		});

		ClientConfigurationConnectionEvents.DISCONNECT.register((listener, client) -> {
			currentConfigurationAddon = null;
		});

		// Version packet
		ClientConfigurationNetworking.registerGlobalReceiver(CommonVersionPayload.TYPE, (listener, context) -> {
			int negotiatedVersion = handleVersionPacket(listener, context.responseSender());
			ClientNetworkingImpl.getClientConfigurationAddon().onCommonVersionPacket(negotiatedVersion);
		});

		// Register packet
		ClientConfigurationNetworking.registerGlobalReceiver(CommonRegisterPayload.TYPE, (listener, context) -> {
			ClientConfigurationNetworkAddon addon = ClientNetworkingImpl.getClientConfigurationAddon();

			if (CommonRegisterPayload.PLAY_PROTOCOL.equals(listener.protocol())) {
				if (listener.version() != addon.getNegotiatedVersion()) {
					throw new IllegalStateException("Negotiated common packet version: %d but received packet with version: %d".formatted(addon.getNegotiatedVersion(), listener.version()));
				}

				addon.getChannelInfoHolder().fabric_getPendingChannelsNames(ConnectionProtocol.PLAY).addAll(listener.channels());
				NetworkingImpl.LOGGER.debug("Received accepted channels from the server");
				context.responseSender().sendPacket(new CommonRegisterPayload(addon.getNegotiatedVersion(), CommonRegisterPayload.PLAY_PROTOCOL, ClientPlayNetworking.getGlobalReceivers()));
			} else {
				addon.onCommonRegisterPacket(listener);
				context.responseSender().sendPacket(addon.createRegisterPayload());
			}
		});
	}

@Override
  public float modifyDamageTaken(IToolStackView tool, ModifierEntry modifier, EquipmentContext context, EquipmentSlot slotType, DamageSource source, float amount, boolean isDirectDamage) {
    LivingEntity entity = context.getEntity();
    // entity must not have enderference, and conditions must match
    if (!entity.hasEffect(TinkerEffects.enderference.get()) && this.defender.matches(entity) && damageSource.matches(source)) {
      // chance of applying is boosted when blocking with a shield
      float level = CounterModule.getLevel(tool, modifier, slotType, entity);
      if (entity.getRandom().nextFloat() < chance.compute(level) && TeleportHelper.randomNearbyTeleport(context.getEntity(), (e, x, y, z) -> new EnderdodgingTeleportEvent(e, x, y, z, modifier))) {
        // if we successfully teleport, apply the cooldown
        int cooldown = this.cooldown.compute(level);
        if (cooldown > 0) {
          entity.addEffect(new MobEffectInstance(TinkerEffects.enderference.get(), cooldown));
        }
        // damage tool based on how much damage we blocked
        ToolDamageUtil.damageAnimated(tool, (int)amount, entity, slotType, modifier.getId());
        // prevent said damage
        return 0;
      }
    }
    return amount;
  }

@Override
    public void aiStep() {
        super.aiStep();
        if (Math.abs(firstWidth - INITIAL_WIDTH * getSize()) > 0.01F || Math.abs(firstHeight - INITIAL_HEIGHT * getSize()) > 0.01F) {
            firstWidth = INITIAL_WIDTH * getSize();
            firstHeight = INITIAL_HEIGHT * getSize();
        }
        if (this.getAnimation() == ANIMATION_SPAWN && this.getAnimationTick() < 30) {
            BlockState belowBlock = level.getBlockState(this.blockPosition().below());
            if (belowBlock.getBlock() != Blocks.AIR) {
                for (int i = 0; i < 5; i++) {
                    this.level.addParticle(new BlockParticleOption(ParticleTypes.BLOCK, belowBlock), this.getX() + (double) (this.random.nextFloat() * this.getBbWidth() * 2.0F) - (double) this.getBbWidth(), this.getBoundingBox().minY, this.getZ() + (double) (this.random.nextFloat() * this.getBbWidth() * 2.0F) - (double) this.getBbWidth(), this.random.nextGaussian() * 0.02D, this.random.nextGaussian() * 0.02D, this.random.nextGaussian() * 0.02D);
                }
            }
            this.setDeltaMovement(0, this.getDeltaMovement().y, 0);
        }
        if (this.getTarget() != null && this.distanceTo(this.getTarget()) < 4 && this.hasLineOfSight(this.getTarget())) {
            if (this.getAnimation() == NO_ANIMATION) {
                this.setAnimation(ANIMATION_BITE);
            }
            this.lookAt(this.getTarget(), 360, 80);
            if (this.getAnimation() == ANIMATION_BITE && this.getAnimationTick() == 6) {
                this.getTarget().hurt(DamageSource.mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
                // After calling hurt the target can become null due to forge hooks
                if (this.getTarget() != null)
                    this.getTarget().knockback(0.25F, this.getX() - this.getTarget().getX(), this.getZ() - this.getTarget().getZ());
            }
        }

        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@Override
    protected void onHit(HitResult result) {
        if(result instanceof EntityHitResult) {
            EntityHitResult rayR = (EntityHitResult) result;
            rayR.getEntity().hurt(DamageSource.thrown(this, this.getOwner()), 8);
            if(!this.level.isClientSide) {
                if(rayR.getEntity() instanceof Player) {
                    Player player = (Player) rayR.getEntity();
                    int blindnessTicks = 0;
                    switch (player.getCommandSenderWorld().getDifficulty()) {
                        case EASY:
                            blindnessTicks = 40;
                            break;
                        case NORMAL:
                            blindnessTicks = 60;
                            break;
                        case HARD:
                            blindnessTicks = 80;
                            break;
                    }
                    player.addEffect(new MobEffectInstance(MobEffects.BLINDNESS, blindnessTicks, 10, false, false));
                }
            }
        }

        if (!this.level.isClientSide) {
            this.level.broadcastEntityEvent(this, (byte) 3);
            this.discard();
        }
    }

@Override
	public void aiStep() {
		if (!this.onGround() && this.getDeltaMovement().y() < 0.0D) {
			Vec3 motion = getDeltaMovement();
			this.setDeltaMovement(motion.x(), motion.y() * 0.6D, motion.z());
		}
		super.aiStep();
		if (this.level().isClientSide() && !this.isDeadOrDying()) {
			// make snow particles
			for (int i = 0; i < 3; i++) {
				float px = (this.getRandom().nextFloat() - this.getRandom().nextFloat()) * 0.3F;
				float py = this.getEyeHeight() + (this.getRandom().nextFloat() - this.getRandom().nextFloat()) * 0.5F;
				float pz = (this.getRandom().nextFloat() - this.getRandom().nextFloat()) * 0.3F;

				this.level().addParticle(TFParticleType.SNOW_GUARDIAN.get(), this.xOld + px, this.yOld + py, this.zOld + pz, 0, 0, 0);
//				if (this.level().getBiome(this.blockPosition()).is(BiomeTags.SNOW_GOLEM_MELTS)) {
//					if (this.random.nextInt(4) == 0) this.level().addParticle(ParticleTypes.CLOUD, this.xOld + px, this.yOld + py, this.zOld + pz, 0, 0.1F, 0);
//					if (this.random.nextBoolean()) this.level().addParticle(ParticleTypes.FALLING_WATER, this.xOld + px, this.yOld + py, this.zOld + pz, 0, 0, 0);
//				}
			}
		}
		if (this.level() instanceof ServerLevel server) {
			if (server.environmentAttributes().getValue(EnvironmentAttributes.SNOW_GOLEM_MELTS, this.blockPosition()) && this.tickCount % 20 == 0) {
				//BURN!!!
				this.hurt(this.damageSources().onFire(), 1.0F);
				for (int i = 0; i < 3; i++) {
					float px = (this.getRandom().nextFloat() - this.getRandom().nextFloat()) * 0.3F;
					float py = this.getEyeHeight() + (this.getRandom().nextFloat() - this.getRandom().nextFloat()) * 0.5F;
					float pz = (this.getRandom().nextFloat() - this.getRandom().nextFloat()) * 0.3F;

					if (this.random.nextInt(4) == 0) this.level().addParticle(ParticleTypes.CLOUD, this.xOld + px, this.yOld + py, this.zOld + pz, 0, 0.1F, 0);
					if (this.random.nextBoolean()) this.level().addParticle(ParticleTypes.FALLING_WATER, this.xOld + px, this.yOld + py, this.zOld + pz, 0, 0, 0);
				}
			}
		}
	}

public void tick() {
        boolean flag = this.inWater;
        if (!flag) {
            FluidState fluidstate = this.dolphin.level().getFluidState(this.dolphin.blockPosition());
            this.inWater = fluidstate.is(FluidTags.LAVA) || fluidstate.is(FluidTags.WATER);
        }
        if(attackCooldown > 0){
            attackCooldown--;
        }
        if (this.inWater && !flag) {
            this.dolphin.playSound(SoundEvents.DOLPHIN_JUMP, 1.0F, 1.0F);
        }
        LivingEntity target = this.dolphin.getTarget();
        if(target != null){
            if(this.dolphin.distanceTo(target) < 3F && attackCooldown <= 0){
                this.dolphin.doHurtTarget(target);
                attackCooldown = 20;
            }
        }

        Vec3 vector3d = this.dolphin.getDeltaMovement();
        if (vector3d.y * vector3d.y < (double) 0.1F && this.dolphin.getXRot() != 0.0F) {
            this.dolphin.setXRot(Mth.rotLerp(this.dolphin.getXRot(), 0.0F, 0.2F));
        } else {
            double d0 = Math.sqrt(vector3d.horizontalDistanceSqr());
            double d1 = Math.signum(-vector3d.y) * Math.acos(d0 / vector3d.length()) * (double) Mth.RAD_TO_DEG;
            this.dolphin.setXRot((float) d1);
        }

    }

@Override
	public void tick(BlockState state, ServerLevel world, BlockPos pos, RandomSource rand) {
		super.tick(state, world, pos, rand);

		int currentAge = state.getValue(GROWTH_STAGE);

		if (currentAge < 6) {
			if (world.getDifficulty() == Difficulty.PEACEFUL) {
				world.setBlockAndUpdate(pos, Blocks.AIR.defaultBlockState());

				ItemEntity itemEntity = new ItemEntity(EntityType.ITEM, world);

				itemEntity.setItem(new ItemStack(AoAItems.PETALS.get()));
				itemEntity.setPos(pos.getX(), pos.getY() + 0.5d, pos.getZ());
				world.addFreshEntity(itemEntity);
			}
			else if (currentAge == 5) {

				/*VinocorneEntity vinocorne = new VinocorneEntity(AoAMobs.VINOCORNE.get(), world);

				vinocorne.setPos(pos.getX(), pos.getY(), pos.getZ());
				world.addFreshEntity(vinocorne);
				world.setBlockAndUpdate(pos, Blocks.AIR.defaultBlockState());*/
			}
			else {
				world.setBlockAndUpdate(pos, defaultBlockState().setValue(GROWTH_STAGE, currentAge + 1));
				world.scheduleTick(pos, state.getBlock(), 40);
			}
		}
